// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(uint56 changeFeeArg, uint16 feeRateArg) public {
        uint56 boundedChangeFee = uint56(bound(uint256(changeFeeArg), 0, 100_000));
        uint16 boundedFeeRate = uint16(bound(uint256(feeRateArg), 0, 5_000));

        c.initialize(
            address(0),
            address(0),
            1e18,
            1e18,
            boundedChangeFee,
            boundedFeeRate,
            bytes32(0),
            false,
            false
        );

        assertTrue(
            c.changeFee() == boundedChangeFee,
            "changeFee must equal the _changeFee argument passed to initialize"
        );
    }
}
